@push('scripts')<script>(()=>{const advanced=document.getElementById('productionAdvanced');document.getElementById('productionFilterToggle')?.addEventListener('click',()=>advanced.toggleAttribute('hidden'));const boxes=[...document.querySelectorAll('.card-select')],count=document.getElementById('selectedCount');const sync=()=>{if(count)count.textContent=boxes.filter(box=>box.checked).length};boxes.forEach(box=>box.addEventListener('change',sync));document.getElementById('selectAll')?.addEventListener('change',event=>{boxes.forEach(box=>box.checked=event.target.checked);sync()});document.getElementById('bulkForm')?.addEventListener('submit',event=>{const selected=boxes.filter(box=>box.checked),target=event.currentTarget.elements.status.value,required={for_printing:'pending',printed:'for_printing',ready_for_release:'printed'}[target],eligible=selected.filter(box=>box.dataset.status===required).length,ineligible=selected.length-eligible;if(!selected.length||!confirm(`Confirm production action? Selected: ${selected.length}. Eligible: ${eligible}. Ineligible: ${ineligible}. Resulting status: ${target.replaceAll('_',' ')}.`))event.preventDefault()})})();</script>@endpush